// ═══ CREATE VIRTUAL THREADS (Java 21) ═══

// Method 1: Thread.startVirtualThread
Thread vt = Thread.startVirtualThread(() -> {
    log.info("Running on: {}", Thread.currentThread());
    // blocking I/O is CHEAP — JVM unmounts this virtual thread
    String result = httpClient.send(request, BodyHandlers.ofString()).body();
});

// Method 2: Executors.newVirtualThreadPerTaskExecutor
try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
    // Submit 100,000 tasks — each gets its own virtual thread!
    List<Future<String>> futures = new ArrayList<>();
    for (int i = 0; i < 100_000; i++) {
        int taskId = i;
        futures.add(executor.submit(() -> {
            Thread.sleep(Duration.ofMillis(100));  // blocking sleep — FREE with virtual threads!
            return "Task-" + taskId + " done on " + Thread.currentThread();
        }));
    }
    // All 100K complete in ~100ms (not 100K × 100ms)!
}

// Method 3: Thread.ofVirtual().factory() for structured concurrency
ThreadFactory factory = Thread.ofVirtual().name("vt-", 0).factory();
ExecutorService executor = Executors.newThreadPerTaskExecutor(factory);

// ═══ SPRING BOOT: enable virtual threads ═══
// application.yml:
// spring.threads.virtual.enabled: true
// All request-handling threads become virtual — instant scalability!

// ═══ WHEN VIRTUAL THREADS DON'T HELP ═══
// CPU-bound: Math.sin() in a tight loop — carrier stays occupied, no unmounting
// Virtual thread adds overhead (~context switch) without benefit for CPU work
// Use parallelStream() or ForkJoinPool for CPU-bound tasks instead

// ═══ THREAD PINNING ═══
synchronized (lock) {  // (Caution) PINNING: virtual thread can't unmount!
    dbConnection.query("SELECT ...");  // blocks carrier thread!
}
// FIX:
ReentrantLock lock = new ReentrantLock();
lock.lock();
try {
    dbConnection.query("SELECT ...");  // virtual thread CAN unmount!
} finally { lock.unlock(); }
// Java 24 (JEP 491) removes synchronized pinning — but ReentrantLock still preferred for timeouts
