package com.bank.virtual;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.time.Duration;
import static org.assertj.core.api.Assertions.*;

class VirtualThreadTest {

    @Test void virtualThreadIsVirtual() throws Exception {
        Thread vt = Thread.startVirtualThread(() -> {});
        vt.join();
        assertThat(vt.isVirtual()).isTrue();
    }

    @Test void platformThreadIsNotVirtual() throws Exception {
        Thread pt = new Thread(() -> {});
        pt.start();
        pt.join();
        assertThat(pt.isVirtual()).isFalse();
    }

    @Test void manyVirtualThreadsConcurrently() throws Exception {
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            var futures = new java.util.ArrayList<Future<String>>();
            for (int i = 0; i < 10_000; i++) {
                int id = i;
                futures.add(executor.submit(() -> "done-" + id));
            }
            assertThat(futures).hasSize(10_000);
            assertThat(futures.get(0).get()).startsWith("done-");
        }
    }

    @Test void virtualThreadBlockingIsCheap() throws Exception {
        long start = System.currentTimeMillis();
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            var futures = new java.util.ArrayList<Future<Void>>();
            for (int i = 0; i < 1000; i++) {
                futures.add(executor.submit(() -> {
                    Thread.sleep(Duration.ofMillis(100));  // blocking — cheap!
                    return null;
                }));
            }
            for (var f : futures) f.get();
        }
        long elapsed = System.currentTimeMillis() - start;
        // 1000 tasks × 100ms sleep ≈ 100-200ms total (not 100,000ms!)
        assertThat(elapsed).isLessThan(5000);
    }
}
